#ch3_decoder_mask {
  --warm-accent: #d97706;
  --warm-light: #fef3c7;
  --cold-accent: #2563eb;
  --mask-color: #e5e7eb;
  --mask-pattern: repeating-linear-gradient(45deg, #e5e7eb, #e5e7eb 10px, #f3f4f6 10px, #f3f4f6 20px);

  font-family: inherit;
  color: var(--ink, #1f2937);
  background: var(--paper, #ffffff);
  padding: 24px;
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  line-height: 1.6;
  font-size: 16px;
}

#ch3_decoder_mask .pm-title {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--ink);
}

#ch3_decoder_mask .pm-lead {
  color: var(--muted, #6b7280);
  margin-bottom: 24px;
}

#ch3_decoder_mask .pm-content-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 24px;
}

@media (max-width: 768px) {
  #ch3_decoder_mask .pm-content-grid {
    grid-template-columns: 1fr;
  }
}

#ch3_decoder_mask .pm-text-block p {
  margin-bottom: 16px;
  text-align: justify;
}

#ch3_decoder_mask .pm-interactive-stage {
  background: var(--warm-light);
  border: 1px solid var(--warm-accent);
  border-radius: 6px;
  padding: 16px;
  margin-top: 24px;
}

#ch3_decoder_mask .pm-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

#ch3_decoder_mask .pm-toggle-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-weight: 500;
}

#ch3_decoder_mask .pm-btn {
  background: var(--ink);
  color: var(--paper);
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
}

#ch3_decoder_mask .pm-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

#ch3_decoder_mask .pm-mask-viz {
  margin: 24px 0;
}

#ch3_decoder_mask .pm-matrix-container {
  display: grid;
  grid-template-columns: 80px 1fr;
  grid-template-rows: 1fr 40px;
  gap: 8px;
  align-items: center;
}

#ch3_decoder_mask .pm-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  grid-template-rows: repeat(5, 1fr);
  gap: 4px;
  aspect-ratio: 1;
  background: #fff;
  padding: 8px;
  border: 1px solid var(--line);
}

#ch3_decoder_mask .pm-cell {
  border: 1px solid var(--line);
  border-radius: 2px;
  transition: all 0.2s;
}

#ch3_decoder_mask .pm-cell.allowed {
  background: var(--warm-accent);
  opacity: 0.8;
}

#ch3_decoder_mask .pm-cell.masked {
  background: var(--mask-pattern);
  opacity: 0.5;
}

#ch3_decoder_mask .pm-cell.current {
  border: 2px solid var(--cold-accent);
  transform: scale(1.05);
  z-index: 2;
}

#ch3_decoder_mask .pm-axis-label {
  font-size: 12px;
  color: var(--muted);
  text-align: center;
}

#ch3_decoder_mask .pm-legend {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-top: 12px;
  font-size: 13px;
}

#ch3_decoder_mask .pm-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 2px;
  margin-right: 4px;
}

#ch3_decoder_mask .pm-allowed { background: var(--warm-accent); }
#ch3_decoder_mask .pm-masked { background: var(--mask-pattern); border: 1px solid #ccc; }
#ch3_decoder_mask .pm-current { border: 2px solid var(--cold-accent); background: #fff; }

#ch3_decoder_mask .pm-viz-note {
  font-size: 12px;
  color: var(--muted);
  text-align: center;
  margin-top: 8px;
  font-style: italic;
}

#ch3_decoder_mask .pm-stepper {
  border-top: 1px solid var(--line);
  padding-top: 16px;
  margin-top: 16px;
}

#ch3_decoder_mask .pm-step-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

#ch3_decoder_mask .pm-step-content {
  background: #fff;
  padding: 12px;
  border-radius: 4px;
  border: 1px solid var(--line);
  font-size: 14px;
  min-height: 60px;
}

#ch3_decoder_mask .pm-evidence-panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px;
  height: fit-content;
}

#ch3_decoder_mask .pm-source-btn {
  background: transparent;
  border: 1px solid var(--ink);
  color: var(--ink);
  padding: 4px 8px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  margin-bottom: 8px;
}

#ch3_decoder_mask .pm-source-quote {
  font-size: 13px;
  color: var(--muted);
  background: var(--warm-light);
  padding: 8px;
  border-radius: 4px;
  margin: 0;
}

#ch3_decoder_mask .pm-limitations ul {
  font-size: 13px;
  color: var(--muted);
  padding-left: 20px;
  margin-top: 8px;
}
