(function() {
  const scopeId = 'ch3_decoder_mask';
  const matrixSize = 5;
  let currentStep = 0;
  let maskEnabled = true;
  let selectedRow = 2; // Default highlight row

  const steps = [
    { title: "步骤 1：带掩码的自注意力", text: "输入进入第一个子层。此时自注意力机制被施加了掩码，使得当前位置只能看到之前的位置，无法看到未来的位置。" },
    { title: "步骤 2：第一次残差与归一化", text: "掩码自注意力的输出与输入相加，并通过层归一化。" },
    { title: "步骤 3：编码器 - 解码器注意力", text: "数据进入第三个子层。此处 Query 来自解码器上一层的输出，而 Key 和 Value 来自编码器堆栈的输出。" },
    { title: "步骤 4：第二次残差与归一化", text: "编码器 - 解码器注意力的输出经过残差连接和层归一化。" },
    { title: "步骤 5：前馈网络与最终归一化", text: "数据通过前馈网络子层，最后再次进行残差连接和层归一化，完成该解码器层的计算。" }
  ];

  function init() {
    const container = document.getElementById(scopeId);
    if (!container) return;

    const maskToggle = document.getElementById(scopeId + '-mask-toggle');
    const resetBtn = document.getElementById(scopeId + '-reset-btn');
    const prevBtn = document.getElementById(scopeId + '-prev-step');
    const nextBtn = document.getElementById(scopeId + '-next-step');
    const stepIndicator = document.getElementById(scopeId + '-step-indicator');
    const stepText = document.getElementById(scopeId + '-step-text');
    const grid = document.getElementById(scopeId + '-matrix-grid');
    const sourceBtn = container.querySelector('[data-source="S001"]');

    // Render Matrix
    function renderMatrix() {
      grid.innerHTML = '';
      for (let i = 0; i < matrixSize; i++) {
        for (let j = 0; j < matrixSize; j++) {
          const cell = document.createElement('div');
          cell.className = 'pm-cell';

          // Logic: Mask if j > i (Future positions)
          const isMasked = maskEnabled && (j > i);
          const isCurrentRow = (i === selectedRow);
          const isCurrentCell = (i === selectedRow && j === selectedRow);

          if (isMasked) {
            cell.classList.add('masked');
            cell.setAttribute('aria-label', `位置 ${i} 无法关注未来位置 ${j}`);
          } else {
            cell.classList.add('allowed');
            if (isCurrentRow) {
              cell.style.opacity = '1';
            } else {
              cell.style.opacity = '0.3';
            }
          }

          if (isCurrentCell) {
            cell.classList.add('current');
          }

          // Interaction: Click cell to select row
          cell.addEventListener('click', () => {
            selectedRow = i;
            renderMatrix();
          });

          grid.appendChild(cell);
        }
      }
    }

    function updateStep() {
      stepIndicator.textContent = `步骤 ${currentStep + 1} / ${steps.length}`;
      stepText.textContent = steps[currentStep].text;
      prevBtn.disabled = currentStep === 0;
      nextBtn.disabled = currentStep === steps.length - 1;
    }

    // Event Listeners
    if (maskToggle) {
      maskToggle.addEventListener('change', (e) => {
        maskEnabled = e.target.checked;
        renderMatrix();
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', () => {
        maskEnabled = true;
        if (maskToggle) maskToggle.checked = true;
        selectedRow = 2;
        currentStep = 0;
        renderMatrix();
        updateStep();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', () => {
        if (currentStep > 0) {
          currentStep--;
          updateStep();
        }
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        if (currentStep < steps.length - 1) {
          currentStep++;
          updateStep();
        }
      });
    }

    if (sourceBtn) {
      sourceBtn.addEventListener('click', () => {
        // Host kernel handles source navigation via data-source attribute
        // No action needed here per spec
      });
    }

    // Initial Render
    renderMatrix();
    updateStep();
  }

  // Wait for DOM
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
